#!/usr/bin/env node
/**
 * Produce the artifacts the sidecar needs to deploy WITHOUT cdk/npm at the user's
 * runtime, and embed them in a generated TS module the sidecar imports:
 *
 *   infra/src/template.ts      ──esbuild──▶ evaluate ──┐
 *   lambdas/src/agent-runner.ts ──esbuild──▶ zip ──────┴─▶ backend/src/generated/backend-bundle.ts
 *
 * (MailPoppy's proven backend-bundle pattern.) Both artifacts are content-addressed:
 *   - `templateKey`   — hash of the template bytes, so the sidecar can tell "the stack
 *     already runs exactly this" from "the app shipped a new template".
 *   - `lambdaCodeKey` — hash of the bundled handler bytes; the zip is uploaded under
 *     this key, so identical code re-uploads idempotently and a code change is a real,
 *     visible stack update (a new key = a new parameter value).
 * The zip is deterministic (STORED, sorted entries, fixed mtime) so the same commit
 * yields byte-identical artifacts on any machine.
 *
 * ⚠️  STALE-SIDECAR TRAP (CLAUDE.md gotcha #1): the sidecar EMBEDS this output. After
 *     ANY change under infra/ or lambdas/: rebuild the sidecar and fully restart
 *     AgentsPoppy, or deploys silently report NO_CHANGE with old code.
 *     `npm run build:sidecar` runs this first (prebuild:sidecar) so the two can't drift.
 *
 * Run from the repo root:  npm run gen:backend
 */
import * as esbuild from "esbuild";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { tmpdir } from "node:os";
import { deterministicZip } from "./lib/deterministic-zip.mjs";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const genDir = join(root, "backend", "src", "generated");

/** The Lambda handlers baked into the stack. P1 adds the dispatcher etc. here. */
const HANDLERS = ["agent-runner", "approval", "mobile-api"];

const git = (args) => {
  try {
    return execFileSync("git", args, { cwd: root }).toString().trim();
  } catch {
    return "";
  }
};

async function main() {
  const staging = join(tmpdir(), `crewpoppy-gen-${process.pid}`);
  mkdirSync(staging, { recursive: true });

  // 1. Bundle + evaluate the template builder. (It's TypeScript, and it's the single
  //    source of truth for the stack — we never hand-maintain a parallel JSON copy.)
  console.log("[1/3] evaluate infra/src/template.ts");
  const templateOut = join(staging, "template.mjs");
  await esbuild.build({
    entryPoints: [join(root, "infra", "src", "template.ts")],
    outfile: templateOut,
    bundle: true,
    platform: "node",
    format: "esm",
    target: "node20",
    logLevel: "warning",
  });
  const { buildTemplate, STACK_NAME, TABLE_NAME, RUNNER_FUNCTION_NAME } = await import(
    pathToFileURL(templateOut).href
  );

  // Stable key order + 2-space indent: the template builder is pure, so these bytes
  // (and therefore templateKey) are identical on every machine at the same commit.
  const templateJson = JSON.stringify(buildTemplate(), null, 2);
  const templateKey = `template-${createHash("sha256").update(templateJson).digest("hex").slice(0, 16)}`;

  // 2. Bundle the Lambda handlers into a deterministic, content-addressed zip.
  //    minify:true is reproducibility-critical (MailPoppy's lesson): without it esbuild
  //    emits module-boundary comments encoding the node_modules layout, which differs
  //    between valid installs and would break the content address.
  console.log("[2/3] bundle lambdas →", HANDLERS.join(", "));
  const entries = [];
  const hash = createHash("sha256");
  for (const name of HANDLERS) {
    const outfile = join(staging, `${name}.js`);
    await esbuild.build({
      entryPoints: [join(root, "lambdas", "src", `${name}.ts`)],
      outfile,
      bundle: true,
      platform: "node",
      format: "cjs",
      target: "node20",
      minify: true,
      legalComments: "none",
      logLevel: "warning",
    });
    const data = readFileSync(outfile);
    hash.update(data);
    entries.push({ name: `${name}.js`, data });
  }
  const lambdaCodeKey = `lambda-code-${hash.digest("hex").slice(0, 16)}.zip`;
  const epoch = Number(process.env.SOURCE_DATE_EPOCH || git(["log", "-1", "--format=%ct"]) || 0);
  const zip = deterministicZip(entries, epoch);
  rmSync(staging, { recursive: true, force: true });

  // 3. Emit the module the sidecar imports. Git-ignored: it is a build output, and
  //    committing it would let it drift from infra/ + lambdas/.
  console.log("[3/3] generate backend/src/generated/backend-bundle.ts");
  mkdirSync(genDir, { recursive: true });
  writeFileSync(
    join(genDir, "backend-bundle.ts"),
    [
      "// AUTO-GENERATED by scripts/build-backend-bundle.mjs — do not edit (git-ignored).",
      "// Rebuild with `npm run gen:backend` after ANY change under infra/ or lambdas/.",
      `export const stackName = ${JSON.stringify(STACK_NAME)};`,
      `export const tableName = ${JSON.stringify(TABLE_NAME)};`,
      `export const runnerFunctionName = ${JSON.stringify(RUNNER_FUNCTION_NAME)};`,
      `export const templateKey = ${JSON.stringify(templateKey)};`,
      `export const templateJson = ${JSON.stringify(templateJson)};`,
      `export const lambdaCodeKey = ${JSON.stringify(lambdaCodeKey)};`,
      `export const lambdaZipBase64 = ${JSON.stringify(zip.toString("base64"))};`,
      `export const sourceCommit = ${JSON.stringify(git(["rev-parse", "HEAD"]))};`,
      "",
    ].join("\n"),
  );

  console.log(
    `\n✅ backend bundle ready (${templateKey}, ${lambdaCodeKey}, zip ${(zip.length / 1024).toFixed(1)} KB)`,
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
